<?php
require __DIR__ . '/room-data.php';
$roomPublicId = (string)($_GET['id'] ?? '');
$room = null;
if (preg_match('/^[A-Za-z0-9]{14}$/', $roomPublicId)) {
    foreach ($rooms as $candidate) { if (hash_equals((string)$candidate['public_id'], $roomPublicId)) { $room = $candidate; break; } }
}
if (!$room) { http_response_code(404); ?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Room unavailable — Cox Booking</title><body><main><h1>Room unavailable</h1><p>This room may have been removed or is no longer available.</p><a href="index.php#room-categories">Browse room categories</a></main></body></html><?php exit; }
$category = $roomCategories[$room['category']];
$submitted = false;
$requestError = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    try { verify_csrf();
        $stmt = $pdo->prepare("INSERT INTO requests(request_type,room_id,room_name,guest_name,email,phone,preferred_reply,checkin_date,checkout_date,guests,notes) VALUES('booking',?,?,?,?,?,'Email or WhatsApp',?,?,?,?)");
        $stmt->execute([$room['id'], $room['name'], trim($_POST['name'] ?? ''), trim($_POST['email'] ?? ''), trim($_POST['phone'] ?? ''), trim($_POST['checkin'] ?? ''), trim($_POST['checkout'] ?? ''), trim($_POST['guests'] ?? ''), trim($_POST['notes'] ?? '')]);
        $submitted = true;
    } catch (Throwable $error) { $requestError = 'We could not send your request just now. Please try again or contact us directly.'; }
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($room['name'])?> — Cox Booking</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Hind+Siliguri:wght@400;500;600;700&family=Noto+Serif+Bengali:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="bengali-ui.css"><link rel="stylesheet" href="pages.css"><link rel="stylesheet" href="forms.css"><link rel="stylesheet" href="responsive.css"><link rel="stylesheet" href="rooms.css?v=5"></head><body><?php include 'partials.php'; ?><main class="room-detail wrap"><a class="back-link" href="rooms.php?category=<?=rawurlencode($room['category'])?>">← <?=e($category['title'])?> rooms</a><div class="room-detail-grid"><div class="room-detail-main"><div class="room-photo-gallery" aria-label="Photos of <?=e($room['name'])?>"><?php foreach ($room['images'] as $photoIndex => $image): ?><figure class="room-gallery-photo"><a class="gallery-trigger" href="<?=e(roomPhoto($image, 1800))?>" target="_blank" rel="noopener" aria-label="View photo <?=$photoIndex + 1?> of <?=count($room['images'])?>: <?=e($room['name'])?>"><img src="<?=e(roomPhoto($image, $photoIndex === 0 ? 1600 : 1000))?>" alt="<?=e($room['name'])?> — photo <?=$photoIndex + 1?>"><span class="gallery-zoom" aria-hidden="true">↗</span></a></figure><?php endforeach; ?></div><div class="room-detail-title"><div><div class="eyebrow"><span></span> <?=e($category['title'])?></div><h1><?=e($room['name'])?></h1><p><?=e($room['location'])?></p></div><div class="detail-price">From <b><?=e($room['price'])?></b><small>per night</small></div></div><p class="room-description"><?=e($room['description'])?></p><div class="room-facts"><span><?=e($room['size'])?></span><span>Up to <?=e($room['guests'])?></span></div><h2 class="amenities-title">Room amenities</h2><div class="detail-amenities"><?php foreach ($room['amenities'] as $amenity): ?><span><?=e($amenity)?></span><?php endforeach; ?></div></div><aside class="room-request-card" id="request"><?php if ($submitted): ?><div class="success"><span>✓</span><h2>Request received</h2><p>Your request for <?=e($room['name'])?> has been noted. We’ll reply by email or WhatsApp within six hours to confirm availability.</p><a class="text-link" href="index.php">Back to Cox Booking <b>↗</b></a></div><?php else: ?><?php if($requestError): ?><div class="admin-alert"><?=e($requestError)?></div><?php endif; ?><div class="request-card-label">ROOM REQUEST</div><h2>Ask about this room</h2><p class="request-room-name"><?=e($room['name'])?> · <?=e($room['price'])?> / night</p><form method="post" action="room.php?id=<?=rawurlencode($room['public_id'])?>#request"><?=csrf_field()?><label>Your name<input required name="name" autocomplete="name" placeholder="Your name"></label><label>Email address<input required type="email" name="email" autocomplete="email" placeholder="you@example.com"></label><label>WhatsApp number<input required type="tel" name="phone" autocomplete="tel" placeholder="+880 1XXX XXXXXX"></label><div class="room-date-row"><label>Check-in<input required name="checkin" placeholder="DD / MM / YYYY" inputmode="numeric"></label><label>Check-out<input required name="checkout" placeholder="DD / MM / YYYY" inputmode="numeric"></label></div><label>Number of guests<input name="guests" placeholder="e.g. 2 adults"></label><label>Anything else?<textarea name="notes" rows="3" placeholder="Your room or trip preferences"></textarea></label><button class="button submit-button" type="submit">Request this room <span>↗</span></button><small class="request-note">This is a request, not a confirmed booking. We’ll respond within 6 hours.</small></form><?php endif; ?></aside></div></main><?php include 'footer.php'; ?></body></html>
